    37→// create a vault for storing underlying assets and market coin supplies
    38→public(package) fun new<MarketType, CoinType>(ctx: &mut TxContext, now: u64): Reserve<MarketType> {
    39→    let mut reserve = Reserve {
    40→        id: object::new(ctx),
    41→        cash: 0,
    42→        debt: float::zero(),
    43→        cash_reserve: float::zero(),
    44→        total_supply: 0,
    45→
    46→        borrow_index: borrow_index::new(now),
    47→    };
    48→
    49→    dynamic_field::add(
    50→        &mut reserve.id,
    51→        ReserveBalanceKey {},
    52→        ReserveBalance<MarketType, CoinType> {
    53→            underlying_balance: balance::zero<CoinType>(),
    54→            ctoken_supply: balance::create_supply(ctoken::new()),
    55→        }
    56→    );
    57→
    58→    reserve
    59→}
